"""Migration of the Meridian CRM credit-hold sweep."""

from decimal import Decimal
from fractions import Fraction
from typing import Any


def _numeric(value: Any) -> Fraction:
    """Return a numeric value using exact decimal semantics; empty is zero."""
    if value is None or value == "":
        return Fraction(0)

    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Fraction(0)

    if isinstance(value, Fraction):
        return value
    if isinstance(value, Decimal):
        return Fraction(value)
    if isinstance(value, bool):
        return Fraction(int(value))
    if isinstance(value, int):
        return Fraction(value)

    # Converting through str preserves the intended decimal representation of
    # floats rather than their binary floating-point approximation.
    return Fraction(Decimal(str(value)))


def _primary_key_sort_value(account: dict, input_index: int) -> tuple:
    """Create a deterministic ascending primary-key ordering value."""
    acct_id = account.get("ACCT_ID")

    if isinstance(acct_id, (int, float, Decimal, Fraction)) and not isinstance(
        acct_id, bool
    ):
        return (0, _numeric(acct_id), input_index)

    if isinstance(acct_id, str):
        return (1, acct_id, input_index)

    return (2, type(acct_id).__name__, repr(acct_id), input_index)


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """
    Apply the nightly credit-hold sweep without mutating the supplied rows.

    Accounts are returned in their original input order, while processing and
    audit generation follow ascending ACCT_ID order.
    """
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    ordered_accounts = sorted(
        enumerate(accounts),
        key=lambda item: _primary_key_sort_value(item[1], item[0]),
    )

    for account_index, account in ordered_accounts:
        if account.get("DEL_FLG") == "Y" or account.get("ACCT_TYP") != "C":
            continue

        acct_id = account.get("ACCT_ID")
        exposure = Fraction(0)

        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _numeric(order.get("TOT_AMT"))

        limit = _numeric(account.get("CRED_LIMIT"))
        updated = new_accounts[account_index]

        if exposure > limit and updated.get("CRED_HOLD") != "Y":
            updated["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        # Intentionally evaluated after the hold-on rule, matching the legacy
        # script's separate second IF statement.
        if exposure * 10 <= limit * 8 and updated.get("CRED_HOLD") == "Y":
            updated["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
